/* ========================================================================== */
/* BFUSION Hierarchical Gantt — Premium Structural Styles                    */
/* ========================================================================== */
.bfusion-root {
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  background-color: #FFFFFF;
  position: relative;
}
.bfusion-root *,
.bfusion-root *:before,
.bfusion-root *:after {
  box-sizing: border-box;
}
/* Body wraps chart + right-side insight area in a horizontal flex row */
.gnt-body {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: row;
  min-height: 0;
  overflow: hidden;
}
/* Chart Canvas Wrapper Styling */
.bfusion-chart-wrap {
  flex: 1 1 auto;
  min-width: 0;
  height: 100%;
  overflow: auto;
  display: block;
  background: #ffffff;
}
.bfusion-chart-wrap::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}
.bfusion-chart-wrap::-webkit-scrollbar-track {
  background: #f4f5f6;
}
.bfusion-chart-wrap::-webkit-scrollbar-thumb {
  background: #b0bec5;
  border-radius: 4px;
}
.bfusion-chart-wrap::-webkit-scrollbar-thumb:hover {
  background: #78909c;
}
/* ========================================================================== */
/* Insight Area — two stacked side-by-side strip + panel pairs                */
/* ========================================================================== */
.gnt-insight-area {
  flex: 0 0 auto;
  display: flex;
  flex-direction: row;
  height: 100%;
  /* clear-zone for license badge */
  padding-bottom: 24px;
  box-sizing: border-box;
  background: transparent;
  --gnt-insight-font: 11px;
  --gnt-insight-header-font: 12px;
  --gnt-insight-accent: #E8612A;
}
.gnt-pair {
  flex: 0 0 auto;
  display: flex;
  flex-direction: row;
  height: 100%;
}
.gnt-strip {
  flex: 0 0 24px;
  width: 24px;
  background: #F8F9FB;
  border-left: 1px solid #E5E7EB;
  color: #6C757D;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  user-select: none;
  transition: background 0.15s ease, color 0.15s ease;
}
.gnt-strip__arrow {
  font-size: 11px;
  color: var(--gnt-insight-accent, #E8612A);
  line-height: 1;
}
.gnt-strip__label {
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  letter-spacing: 2px;
  font-weight: 600;
  font-size: 9.5px;
  color: #6C757D;
  text-transform: uppercase;
}
.gnt-strip:hover,
.gnt-strip:focus {
  background: #FFFFFF;
  color: #242424;
  outline: none;
}
.gnt-panel {
  flex: 0 0 0;
  width: 0;
  max-width: 320px;
  background: linear-gradient(180deg, #FFFFFF 0%, #F8F9FB 100%);
  border-left: 1px solid #E5E7EB;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  font-size: var(--gnt-insight-font, 11px);
  color: #242424;
  transition: width 0.2s ease, flex-basis 0.2s ease, padding 0.2s ease;
  padding: 0;
}
.gnt-pair--expanded .gnt-panel {
  flex: 0 0 290px;
  width: 290px;
  overflow-y: auto;
  padding: 12px 12px 16px 12px;
  gap: 10px;
}
/* ---- Panel internals ---------------------------------------------------- */
.gnt-panel__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  padding-bottom: 6px;
  border-bottom: 2px solid var(--gnt-insight-accent, #E8612A);
  margin-bottom: 4px;
}
.gnt-panel__title {
  font-size: var(--gnt-insight-header-font, 12px);
  font-weight: 700;
  color: #242424;
  letter-spacing: 0.2px;
}
.gnt-panel__subtitle {
  font-size: calc(var(--gnt-insight-font, 11px) - 1px);
  color: #6C757D;
  margin-top: 2px;
  word-break: break-word;
}
.gnt-panel__badge {
  flex: 0 0 auto;
  color: #fff;
  border-radius: 6px;
  padding: 4px 8px;
  font-size: calc(var(--gnt-insight-font, 11px) + 1px);
  font-weight: 700;
  text-align: center;
  line-height: 1.2;
  min-width: 56px;
}
.gnt-panel__badge-lbl {
  font-size: calc(var(--gnt-insight-font, 11px) - 2px);
  font-weight: 500;
  opacity: 0.92;
}
.gnt-panel__plan-meta {
  font-size: calc(var(--gnt-insight-font, 11px) - 1px);
  color: #6C757D;
}
.gnt-panel__healthbar {
  height: 8px;
  background: #e8eaed;
  border-radius: 4px;
  overflow: hidden;
}
.gnt-panel__healthbar-fill {
  height: 100%;
  border-radius: 4px;
}
.gnt-panel__kpis {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
}
.gnt-kpi {
  background: #FFFFFF;
  border: 1px solid #E5E7EB;
  border-left: 3px solid var(--gnt-kpi-color, #E8612A);
  border-radius: 6px;
  padding: 6px 8px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.gnt-kpi__label {
  font-size: calc(var(--gnt-insight-font, 11px) - 1px);
  color: #6C757D;
  font-weight: 500;
}
.gnt-kpi__value {
  font-size: calc(var(--gnt-insight-font, 11px) + 6px);
  font-weight: 700;
  color: var(--gnt-kpi-color, #242424);
  line-height: 1.1;
  font-variant-numeric: tabular-nums;
}
.gnt-kpi__sub {
  font-size: calc(var(--gnt-insight-font, 11px) - 2px);
  color: #6C757D;
}
.gnt-panel__section {
  margin-top: 4px;
}
.gnt-panel__section-title {
  font-weight: 600;
  color: #6C757D;
  font-size: calc(var(--gnt-insight-font, 11px) - 1px);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 6px;
}
.gnt-panel__statusbar {
  display: flex;
  height: 10px;
  border-radius: 5px;
  overflow: hidden;
  background: #f1f3f5;
}
.gnt-panel__statusbar div {
  transition: width 0.2s ease;
}
.gnt-panel__legend {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  font-size: calc(var(--gnt-insight-font, 11px) - 2px);
  color: #6C757D;
  margin-top: 6px;
}
.gnt-panel__legend span {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.gnt-panel__legend i {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  display: inline-block;
}
.gnt-panel__mini {
  display: flex;
  justify-content: space-between;
  gap: 4px;
  font-size: calc(var(--gnt-insight-font, 11px) - 1px);
  color: #242424;
}
.gnt-panel__mini > div {
  text-align: center;
  flex: 1;
}
.gnt-panel__mini strong {
  font-weight: 700;
}
.gnt-panel__next {
  margin-top: 8px;
  padding: 6px 8px;
  background: #FFFFFF;
  border: 1px solid #E5E7EB;
  border-radius: 6px;
}
.gnt-panel__next-label {
  font-size: 9px;
  color: #6C757D;
  font-weight: 600;
  letter-spacing: 0.5px;
}
.gnt-panel__next-name {
  font-weight: 600;
  margin-top: 2px;
  word-break: break-word;
}
.gnt-panel__next-meta {
  font-size: calc(var(--gnt-insight-font, 11px) - 2px);
  color: #6C757D;
  margin-top: 2px;
}
.gnt-panel__list {
  list-style: none;
  margin: 0;
  padding: 0;
}
.gnt-panel__row {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 6px;
  border-radius: 4px;
  margin-bottom: 3px;
  background: #FFFFFF;
  border: 1px solid #E5E7EB;
}
.gnt-panel__dot {
  flex: 0 0 auto;
  width: 8px;
  height: 8px;
  border-radius: 50%;
}
.gnt-panel__name {
  flex: 1 1 auto;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.gnt-panel__val {
  flex: 0 0 auto;
  font-weight: 600;
  color: #242424;
  font-variant-numeric: tabular-nums;
  font-size: calc(var(--gnt-insight-font, 11px) - 1px);
}
.gnt-panel__empty {
  list-style: none;
  color: #6C757D;
  font-size: calc(var(--gnt-insight-font, 11px) - 1px);
  padding: 4px 0;
}
.gnt-panel__footer {
  margin-top: 4px;
  font-size: 9px;
  color: #bbb;
  text-align: right;
}
/* ---- Narrative panel specifics ----------------------------------------- */
.gnt-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}
.gnt-pill {
  font-size: 9px;
  padding: 2px 7px;
  border-radius: 10px;
  font-weight: 600;
  line-height: 1.4;
}
.gnt-narr {
  background: #FFFFFF;
  border: 1px solid #E5E7EB;
  border-radius: 6px;
  padding: 6px 8px;
}
.gnt-narr__title {
  font-size: calc(var(--gnt-insight-font, 11px));
  font-weight: 700;
  color: #242424;
  margin-bottom: 4px;
}
.gnt-narr__body {
  font-size: calc(var(--gnt-insight-font, 11px) - 1px);
  color: #374151;
  line-height: 1.5;
}
.gnt-actions {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.gnt-action {
  display: flex;
  gap: 6px;
  align-items: flex-start;
}
.gnt-action__badge {
  flex: 0 0 auto;
  color: #fff;
  font-size: 9px;
  font-weight: 700;
  padding: 1px 6px;
  border-radius: 4px;
  white-space: nowrap;
  margin-top: 1px;
}
.gnt-action__body {
  font-size: calc(var(--gnt-insight-font, 11px) - 1px);
  color: #374151;
  line-height: 1.5;
}
/* Narrow viewport: collapse both panels by default; user can still open them */
.bfusion-root.gnt-narrow .gnt-pair--expanded .gnt-panel {
  flex-basis: 240px;
  width: 240px;
}
.bfusion-root.gnt-very-narrow .gnt-pair--expanded .gnt-panel {
  position: absolute;
  right: 24px;
  top: 0;
  bottom: 24px;
  width: 240px;
  z-index: 25;
  box-shadow: -6px 0 18px rgba(15, 23, 42, 0.1);
}
/* ========================================================================== */
/* Responsive Landing Page Framework                                         */
/* ========================================================================== */
.bfusion-landing-wrap {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  background-color: #FFFFFF;
  overflow: auto;
}
.bfusion-landing {
  display: flex;
  flex-direction: column;
  align-items: center;
  max-width: 420px;
  padding: 20px;
  box-sizing: border-box;
  text-align: center;
}
/* Premium Squircle Frame Layout for Logo Images */
.bfusion-landing__logo-container {
  width: 130px;
  height: 84px;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #FF5500;
  /* Blends nicely with the orange branding */
  border-radius: 12px;
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.08);
  margin-bottom: 24px;
  overflow: hidden;
}
.bfusion-landing__logo {
  width: 100%;
  height: 100%;
  object-fit: contain;
  /* Keeps text vectors pristine */
}
.bfusion-landing__text-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
}
.bfusion-landing__title {
  font-size: 15px;
  font-weight: 600;
  color: #242424;
  /* Soft dark grey */
  margin: 0 0 14px 0;
  padding: 0;
  line-height: 1.2;
}
.bfusion-landing__description {
  font-size: 11.5px;
  font-weight: 400;
  color: #666666;
  /* Elegant grey description font */
  margin: 0;
  padding: 0;
  line-height: 1.5;
}
.bfusion-landing__description strong {
  font-weight: 600;
  color: #444444;
}
.bfusion-landing__separator {
  width: 60%;
  height: 1px;
  background-color: #EAEAEA;
  margin: 20px 0;
}
.bfusion-landing__metadata {
  font-size: 10.5px;
  color: #8C8C8C;
  margin-bottom: 4px;
  font-weight: 400;
  line-height: 1.4;
}
.bfusion-landing__metadata strong {
  font-weight: 600;
  color: #707070;
}
/* ========================================================================== */
/* License Badge & Watermark                                                   */
/* ========================================================================== */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
}
.bfusion-license-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  pointer-events: auto;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge--valid {
  background: rgba(5, 150, 105, 0.08);
  border: 1px solid rgba(5, 150, 105, 0.25);
  color: #059669;
}
.bfusion-license-badge--invalid {
  background: rgba(220, 38, 38, 0.06);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: #DC2626;
}
.bfusion-license-badge__icon {
  font-size: 11px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
.bfusion-watermark {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 15;
  pointer-events: none;
  display: flex;
  align-items: center;
  justify-content: center;
  background: repeating-linear-gradient(-45deg, transparent, transparent 120px, rgba(220, 38, 38, 0.03) 120px, rgba(220, 38, 38, 0.03) 122px);
}
.bfusion-watermark__content {
  text-align: center;
  opacity: 0.18;
  user-select: none;
  transform: rotate(-18deg);
}
.bfusion-watermark__title {
  font-size: 56px;
  font-weight: 900;
  color: #DC2626;
  letter-spacing: 12px;
  line-height: 1;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__subtitle {
  font-size: 16px;
  font-weight: 600;
  color: #DC2626;
  margin-top: 6px;
  letter-spacing: 3px;
  text-transform: uppercase;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__link {
  font-size: 11px;
  color: #9CA3AF;
  margin-top: 12px;
  font-family: "Segoe UI", sans-serif;
}
/* ========================================================================== */
/* Empty Data State (cross-filter excluded everything)                        */
/* ========================================================================== */
.bfusion-empty {
  display: flex;
  width: 100%;
  height: 100%;
  align-items: center;
  justify-content: center;
  padding: 20px 24px 28px 24px;
  box-sizing: border-box;
}
.bfusion-empty__message {
  font-size: 12px;
  color: #94a3b8;
  font-weight: 400;
  text-align: center;
  letter-spacing: 0.2px;
}
